112	## Rich schema #1: PKs, AUTOINCREMENT, composite PK, NOT NULL, UNIQUE, DEFAULTs, CHECK
113	
114	Database created with python3 sqlite3:
115	
116	```sql
117	CREATE TABLE users (
118	  id INTEGER PRIMARY KEY AUTOINCREMENT,
119	  name TEXT NOT NULL,
120	  email TEXT NOT NULL UNIQUE,
121	  age INTEGER DEFAULT 18,
122	  bio TEXT DEFAULT 'hello ''world''',
123	  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
124	  score REAL DEFAULT 1.5,
125	  active INTEGER DEFAULT 1,
126	  CONSTRAINT age_check CHECK (age >= 0)
127	);
128	CREATE TABLE posts (
129	  id INTEGER PRIMARY KEY,
130	  user_id INTEGER NOT NULL,
131	  title TEXT NOT NULL DEFAULT 'untitled',
132	  body TEXT,
133	  UNIQUE (user_id, title)
134	);
135	CREATE TABLE composite (
136	  a INTEGER NOT NULL,
137	  b TEXT NOT NULL,
138	  c BLOB,
139	  PRIMARY KEY (a, b)
140	);
141	```
142	
143	Command: `atlas schema inspect -u "sqlite://rich1.db"` — exit 0, stderr empty, stdout verbatim:
