410	## Type mapping, generated columns, WITHOUT ROWID
411	
412	DDL: `CREATE TABLE types (a VARCHAR(255), b DECIMAL(10,2), c NUMERIC, d BOOLEAN, e DATETIME,
413	f DOUBLE PRECISION, g CHAR(10), h CLOB, i INT2, j BIGINT, k UNSIGNED BIG INT, l VARCHAR, m,
414	n INTEGER GENERATED ALWAYS AS (a) VIRTUAL, o TEXT GENERATED ALWAYS AS ('x') STORED);`
415	plus `CREATE TABLE norowid (x INT, y TEXT, PRIMARY KEY(x, y)) WITHOUT ROWID;`
416	
